import{z as B,x as d,o as s,c as p,q as t,j as o,D as e,d as E,s as i,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"排序归并连接","description":"","frontmatter":{"title":"排序归并连接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sort-merge-join.md","filePath":"cs/sort-merge-join.md","lastUpdated":1791413859000}'),A={name:"cs/sort-merge-join.md"};function m(h,a,c,D,_,f){const n=d("Mermaid");return s(),p("div",null,[a[2]||(a[2]=t('<h1 id="排序归并连接" tabindex="-1">排序归并连接 <a class="header-anchor" href="#排序归并连接" aria-label="Permalink to &quot;排序归并连接&quot;">​</a></h1><div class="epigraph"><p>两侧按连接键排序后，像归并两个有序表一样推进指针；等值与某些范围连接都自然。</p><footer>—— 据 Blasgen and Eswaran；Ramakrishnan and Gehrke；对照外存排序</footer></div><p><a href="/cs/nlj-hash-join">上一课</a>收了嵌套循环与哈希。本课不重做分区哈希。缺口是第三种形状：输入若已按键有序（B+ 叶扫描、聚簇），或付得起外存排序，归并连接一次扫过。它也服务非哈希友好的条件。下一课才把算子收成计划树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>哈希要求等值且能选哈希函数。两路归并算法课已教；外存多趟由后课<a href="/cs/external-sort">外部排序</a>展开。连接：两路归并时，键相等则做笛卡尔（在重复组内），然后前进较小的一侧。预排序代价高，但输出自然有序，可能帮下一算子。缺口是<strong>有序归并这一物理合同</strong>。</p><p><span class="marginnote">数字实例：两表按 id 各排好序，左指针停在 3、右指针停在 5——3 小于 5，左边不可能配上 5，左指针前进；两边同时走到 7 且各有一组重复行，就把整组做笛卡尔配对（比如每组 4 行就是 16 对）再一起越过。全程每页数据只顺序读一遍。</span></p><p><span class="marginnote">重复键组很大时，归并要能把一组物化或回绕，否则漏配。这是实现细节，规格仍是代数连接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>若无序：外部排序两侧（或一侧），再归并。若一侧是有序索引扫描，只排另一侧。内存中可用替换选择产生初始顺串。本课不把并行排序的采样划分写完。</p><p><span class="marginnote">术语翻译：「物理合同」就是算子之间的接口承诺——上游保证交给下游的数据按某键有序。排序归并是这份合同最直接的受益者：上游若是 B+ 树叶扫描这种天然有序流，本算子连排序都省了；优化器正是靠物化这种性质砍掉整段排序节点。</span></p>',10)),(s(),o(l,null,{default:e(()=>[i(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%B8%A4%E4%BE%A7%E8%BE%93%E5%85%A5%22%5D%20--%3E%20SORT%5B%22%E6%8C%89%E8%BF%9E%E6%8E%A5%E9%94%AE%E6%8E%92%E5%BA%8F%22%5D%0A%20%20SORT%20--%3E%20MG%5B%22%E5%BD%92%E5%B9%B6%E7%9B%B8%E7%AD%89%E9%94%AE%E7%BB%84%22%5D%0A%20%20IDX%5B%22%E5%B7%B2%E6%9C%89%E5%BA%8F%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20MG%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[E("归并把随机 I/O 换成顺序 I/O，和"),r("a",{href:"/cs/locality-principle"},"局部性"),E(" 一致。与哈希对照：哈希探测是随机桶访问；归并是顺序。优化器后课用页数模型比较三者，而不是「哈希总是更快」。")],-1)),(s(),o(l,null,{default:e(()=>[i(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%B8%A4%E6%8C%87%E9%92%88%E5%90%84%E6%8C%87%E4%B8%80%E4%BE%A7%E5%BD%93%E5%89%8D%E9%94%AE%22%5D%20--%3E%20C%7B%22%E6%AF%94%E8%BE%83%E4%B8%A4%E4%BE%A7%E9%94%AE%22%7D%0A%20%20C%20--%20%22%E5%B7%A6%E9%94%AE%E8%BE%83%E5%B0%8F%22%20--%3E%20L%5B%22%E5%B7%A6%E6%8C%87%E9%92%88%E5%89%8D%E8%BF%9B%22%5D%0A%20%20C%20--%20%22%E5%8F%B3%E9%94%AE%E8%BE%83%E5%B0%8F%22%20--%3E%20R%5B%22%E5%8F%B3%E6%8C%87%E9%92%88%E5%89%8D%E8%BF%9B%22%5D%0A%20%20C%20--%20%22%E7%9B%B8%E7%AD%89%22%20--%3E%20E%5B%22%E7%89%A9%E5%8C%96%E6%95%B4%E7%BB%84%E9%87%8D%E5%A4%8D%E9%94%AE%20%E5%81%9A%E7%BB%84%E5%86%85%E9%85%8D%E5%AF%B9%22%5D%0A%20%20E%20--%3E%20D%5B%22%E4%B8%A4%E4%BE%A7%E9%83%BD%E8%B6%8A%E8%BF%87%E8%AF%A5%E7%BB%84%E5%90%8E%E5%90%8C%E6%97%B6%E5%89%8D%E8%BF%9B%22%5D%0A%20%20L%20--%3E%20P%0A%20%20R%20--%3E%20P%0A%20%20D%20--%3E%20P%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">这张图回答「归并阶段两个指针到底怎么走」：小的那边先走，因为不可能配上对面更大的键；撞上相等键时不能逐行前进——要把整组重复物化或回绕，否则剩下的重复行会漏配，这正是正文提醒的实现坑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 zigzag 连接当主干必选。如何把选择、连接、扫描排成树并交给执行器，下一课查询计划。</p><p><span class="marginnote">常见误区：以为「哈希连接总是更快」。哈希要为构建侧付内存与分区 I/O，而且只做等值；当输入本来就有序、或连接结果接下来还要按该键排序时，排序归并可能整份计划更省——优化器比的是总代价，不是单个算子的名气。</span></p><p>后课默认：三种物理连接都可用。执行的对象是计划树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>排序归并对有序或可排序输入一次扫描。</li><li>输出有序可能被后续算子利用。</li><li>计划树下一课。</li><li>出处：Blasgen and Eswaran；Ramakrishnan and Gehrke。</li></ul>',7))])}const C=B(A,[["render",m]]);export{g as __pageData,C as default};
